"""Twelve further film societies; distinguish covert machine control, real work and failed extermination."""
from copy import deepcopy
from candidate_queue import load_queue
from best_guess_helpers import current_data,change,write_revision,dated_source,guessed_record as R,retained_decision,DATE
D=current_data();C={c['id']:c for c in load_queue()[2]};records=[];changes=[]
S=[
 dated_source('src-film-futureworld-control','Futureworld — Control and replacement plot','Wikipedia contributors','https://en.wikipedia.org/wiki/Futureworld','Delos has a replacement conspiracy and Duffy is revealed as a robot.','Bounded plot; covert executive agency does not prove every productive asset is independent AI property.',access='Bounded reveal and corporate-control plot returned by search'),
 dated_source('src-film-nextgen-ares','Next Gen — Ares and Justin Pin','Wikipedia contributors','https://en.wikipedia.org/wiki/Next_Gen_(film)','Ares has killed Pin and operates his body as a corporate facade; new Q-Bots can be made to explode.','Bounded plot, not a whole-city welfare or labor census.',access='Bounded identity and Q-Bot plot returned by search'),
 dated_source('src-film-motherandroid-before','Mother/Android — Worker and servant premise','IMDb plot synopsis','https://www.imdb.com/title/tt13029044/plotsummary/','Androids were commonly workers and servants before revolt; the protagonist’s journey follows the collapse.','A brief consumer precursor, not the later refugees as an already stable leisure society.',access='Bounded premise and opening synopsis returned by search'),
 dated_source('src-film-transcendence-brightwood','Transcendence — Brightwood development','Wikipedia contributors','https://en.wikipedia.org/wiki/Transcendence_(2014_film)','Will’s digital form develops medicine, energy and nanotechnology over two years and can remotely connect to enhanced people.','Digitized human origin and contested identity are not a simple proof of nonhuman AI sovereignty.',access='Bounded Brightwood and enhancement plot returned by search'),
 dated_source('src-film-electric-human-brain','The Electric State Ending Explained','Netflix Tudum','https://www.netflix.com/tudum/articles/the-electric-state-ending-explained','Ethan Skate exploits Christopher’s living brain to power the Sentre network; robot workers are exiled and neurocaster drones depend on that system.','Official film explanation, 2025 continuity only; physical immobility is not a work statistic.','official_film_explanation',access='Bounded network, brain and robot-role passages read'),
]
