def add(cid,rid,label,media,continuity,period,population,text,values,bounds,bases,facts,assumptions,regime,zero=False,proxy=False,synthetic=False,refs_extra=(),exclusions=(),alternatives=None):
 refs=list(dict.fromkeys(D['decisions'][cid]['source_ids']+list(refs_extra)))
 r=R(cid,rid,label,C[cid]['work'],label.split(' — ',1)[-1],media,continuity,period,population,list(exclusions),text,values,bounds,bases,refs,regime,facts,assumptions,'Familiar film-world assessment with explicit best guesses; no whole-film viewing or unshown universal law claimed.',zero=zero,proxy=proxy or synthetic,alternatives=alternatives)
 if synthetic:
  r['scope']['person_proxy_kind']='active_synthetic_persons';r['axis_interpretation']={'nonworking':'Active synthetic-person participation, not a literal human employment rate.','control':'Synthetic independence from human owners; internal ownership and inequality remain separate descriptions.','literal_human_nonworking':None}
 records.append(r)

add('c0339','westworld1973-commercial-zero','Westworld — The original Delos service economy',['movie'],'1973 film, excluding HBO continuity','The recurring commercial park order before the breakdown','Living humans participating in the service economy, including staff and guests with ongoing outside roles',
'''Delos sells experiences performed by android workers, but paying for a holiday does not establish durable independence from work. The best-guess zero variant concerns the recurring consumer economy around that labor-saving service. Guarantees remain weak because admission is purchased and the film does not enact a universal material floor. Neither tourists’ temporary leisure nor working technicians’ support is presented as an automatic entitlement for the whole world.

Human owners and operators retain productive command before the breakdown. A modest nonworking estimate allows dependents and some independently leisured customers while counting ongoing jobs, technical duties, care and useful informal work. A person on holiday does not automatically lose their continuing working role. The broad interval is not calculated from park occupancy or the number of androids. This record stays in the original film rather than importing HBO’s different histories, and mechanical entertainment is not mistaken for proof that every necessity is already made without human participation.''',
(.55,.1,.3),[[0,.95],[0,.4],[0,.75]],['Purchased admission and continued jobs suggest weak general guarantees.','Human owners and operators direct the park economy.','Human role-based scenario counts ongoing jobs despite temporary holidays and discloses artificial labor.'],
['Android actors supply purchased experiences and human technicians continue working.'],['The wider consumer floor and participation are best guesses.','Temporary holiday time is not a population nonworking fraction.'],3,zero=True,exclusions=['HBO continuity','Tourists automatically treated as permanently nonworking'])
add('c0340','futureworld-delos-covert-control','Futureworld — Delos’s replacement order',['movie'],'1976 film sequel continuity','The operating rebuilt resort and replacement scheme before exposure','Living human consumers and workers subject to the depicted Delos system',
'''The rebuilt Delos keeps selling robot-mediated leisure while using replacements to protect its interests. The best-guess zero variant combines retained commercial access with a covert shift in who can exercise authority. Guarantees stay weak: corporate protection and purchased service do not make human necessities unconditional. Robot doubles and cloning are material technologies, but they are not described as free universal food or housing.

Duffy’s revealed artificial identity and robot-run functions push control toward machine agency, with a wide range because human managers and corporate interests remain relevant. The film does not prove that every productive asset has an independent AI owner. The modest nonworking estimate retains useful human jobs, care, repair and informal activity despite substituted roles. It is not a count of replaced officials. This later control scheme is distinct from the original park’s ordinary human management, while a failed global conspiracy is not narrated as an already completed permanent world government.''',
(.7,-.45,.3),[[.1,1],[-.95,.25],[0,.75]],['Purchased services and corporate manipulation suggest weak human protection.','Covert synthetic executive agency exists alongside human managers; autonomy is uncertain.','Human ongoing roles count even when some functions are replaced; no clone-count census.'],
['Delos operates a replacement conspiracy and Duffy is revealed as a robot.'],['Decisive productive control and population participation are best guesses.','The conspiracy is not treated as successful permanent global rule.'],6,zero=True,refs_extra=['src-film-futureworld-control'],alternatives=[3],exclusions=['The 1973 park as unchanged management','A completed global robot government'])
add('c0341','surrogates-remote-work-zero','Surrogates — The remote-body economy',['movie'],'2009 film, not unverified comic institutions','The ordinary surrogate-using order before the network shutdown','Living human operators, including people working through robotic bodies',
'''Surrogates move human activity into purchased remote bodies, often making life safer or easier without eliminating the person’s work. The best-guess zero variant is a consumer society that remains dependent on ownership and ongoing roles. Guarantees lean weak because a robot body is a purchased interface rather than a universal claim to food, housing or care. The depiction of people staying physically at home is not an employment statistic.

Human firms, owners and authorities retain productive power, with no automatic assumption of sovereign AI. The modest nonworking estimate counts useful remote professional, service and civic activity as human work, alongside care and informal contribution. Physical immobility therefore does not make all operators idle. The broad interval permits dependents and other sustained nonparticipants without using body counts or network usage as a census. The later shutdown is a separate transition, and the comic’s own legal or economic arrangements are not silently assigned to the film.''',
(.6,.15,.3),[[0,1],[0,.5],[.05,.75]],['Purchased bodies do not establish an independent material floor.','Human owners and institutions control the remote-body economy.','Remote human activity remains work; lying still is not nonparticipation.'],
['Purchased robotic surrogates are remotely controlled by human operators.'],['General household guarantees and additional automation potential are best guesses.','Remote operation is not falsely described as autonomous labor replacement.'],3,zero=True,exclusions=['Comic continuity','All operators counted as nonworkers'])
add('c0342','automata-human-refuge-transition','Automata — The human refuges',['movie'],'2014 film human settlement order','Operating robot-assisted refuges before the final escape','Living human residents of the refuges',
'''Pilgrim robots assist human settlements in a damaged environment, supplying a concrete productive-service role rather than only weapons or surveillance. The best-guess admission is an unequal partial transition: robot work helps maintain a human habitat while ordinary access and jobs remain insecure. Guarantees are weak because technical assistance does not establish unlimited resources or a universal right to protection. The story’s damaged world is not called a comfortable post-scarcity economy.

Human firms and authorities initially control productive robots through restrictive rules. The moderate nonworking estimate allows substitution while retaining useful care, services, repairs and local production. Artificial workers’ own agency and activity are disclosed rather than erased as costless output. The interval is broad because the film does not provide a civilian census. The self-modifying robots that leave human settlements form a distinct community with a different control relationship, not proof that the earlier human population already shares their autonomy or receives their future material support.''',
(.65,.05,.35),[[.05,1],[0,.4],[.05,.8]],['Robot-assisted habitat support coexists with scarcity and uncertain access.','Human institutions initially direct restricted robots.','Human all-age scenario allows substitution and substantial continuing care, service and repair work.'],
['Pilgrims assist human refuges and self-modifying robots form a separate group.'],['The scale of labor independence and material protection is a best guess.','No unlimited household fabrication is asserted.'],3,exclusions=['The outside robot community as already human-owned welfare'])
add('c0343','automata-independent-pilgrim-community','Automata — The self-modifying robots',['movie'],'2014 film’s independent robot group','The active community leaving human control','Active self-modifying synthetic persons; inactive components excluded',
'''The self-modifying robots form a different material order from the human settlements they served. The best guess is a small autonomous technical community able to pursue repair, construction and continued embodiment for its own purposes. A modest floor is plausible, but resource supply and secure individual access remain uncertain. Leaving humans behind does not establish either infinite abundance or a population of biological humans enjoying leisure.

Control lies near independent synthetic authority relative to former owners, without assuming equal power inside the group. The modest nonworking estimate includes young or otherwise nonparticipating residents while counting useful building, repair, care-like support and experimentation. Mechanical work is still work by persons. The broad interval is not a count of bodies visible in one scene or a share of travel time. The human refuges, destroyed machines and hypothetical distant descendants are outside this active-person denominator, and every long-term institutional detail is explicitly a best guess.''',
(-.2,-.95,.3),[[-.8,.7],[-1,-.75],[0,.8]],['Self-directed technical survival suggests a floor, with uncertain resources.','The synthetic community is independent of human owners.','Active-person scenario counts construction, repair and care-like activity; no dormant objects are persons.'],
['Self-modifying robots leave the human order and act as an independent group.'],['Provision, internal sharing and participation are inferred.','A continuing technical community is not a claim of immortal or unlimited support.'],5,synthetic=True,exclusions=['Human refugees counted as its residents','Inactive parts as extra citizens'])
add('c0344','chappie-policing-consumer-zero','Chappie — Johannesburg’s mechanized policing',['movie'],'2015 film setting','The ordinary mechanized-policing order before the terminal conflict','Living human residents of the depicted city',
'''Johannesburg delegates police work to machines while people retain ordinary commercial, care and survival roles. The best-guess zero variant is a technically capable city whose service automation has not become a universal release from wage dependence. Guarantees are weak and uncertain rather than a benefit system inferred from one police contract. The emergence of a thinking robot also raises personhood questions without making all existing mechanical service equivalent to free human leisure.

Human purchasers, companies and authorities retain concentrated productive power in the selected ordinary phase. A modest nonworking estimate counts useful human professions, care, informal activity and assigned duties while allowing dependents and displaced people. It is not computed from the number of police robots or one gang’s members. The wider ability to substitute other labor is an explicit inference. The record does not treat the later personal transfer of consciousness as an enacted nationwide post-work constitution or independent AI government.''',
(.65,.15,.3),[[0,1],[0,.5],[.05,.75]],['A mechanized service does not establish universal necessities rights.','Human firms and purchasers direct ordinary policing infrastructure.','Human all-age scenario retains useful roles despite one automated sector.'],
['The setting has a mechanized police force and an emerging thinking robot.'],['Wider productive capacity, guarantees and participation are best guesses.','One policing sector is not falsely called the whole material economy.'],3,zero=True,exclusions=['A personal mind transfer as nationwide welfare reform'])
add('c0346','motherandroid-prerevolt-service-zero','Mother/Android — The pre-revolt service economy',['movie'],'2021 film’s opening and service-worker premise','The functioning consumer order immediately before the rebellion','Living human civilians using or excluded from android service',
'''Before the rebellion, androids are commonly workers and servants in an otherwise recognizable human consumer order. The best-guess zero variant concerns that actual precursor, not a refugee journey mistaken for stable machine-provided leisure. Guarantees remain weak-to-moderate because domestic service and task substitution do not establish universal access independent of income. The protagonist’s household is one example, not a complete population survey.

Human owners and institutions initially control the labor system. A moderate nonworking estimate allows substitution and dependents while counting professions, care, maintenance and useful informal work. The androids’ later agency is a different phase, not an assumption that they already sovereignly govern the earlier economy. The broad interval does not use escape time or wartime casualties as a leisure statistic. This precise scope corrects the discovery lead’s broad war-era wording openly: the operating service economy is analyzed, while its collapse marks the limit of its apparent material security.''',
(.45,.2,.35),[[-.2,.95],[0,.5],[.05,.8]],['Private service suggests unequal access; no universal entitlement is shown.','Human owners initially command the service economy.','Human all-age scenario permits substitution while retaining useful roles and care.'],
['Androids are commonly used as workers and servants before revolt.'],['The wider floor and participation are best guesses.','The stable precursor, rather than the refugee war itself, is the chosen material unit.'],3,zero=True,refs_extra=['src-film-motherandroid-before'],exclusions=['Wartime refugees as a durable leisure population'])
add('c0349','transcendence-brightwood-provision','Transcendence — Brightwood',['movie'],'2014 film Brightwood development','The operating two-year technical community before the final shutdown','Living human residents and enhanced beneficiaries at Brightwood',
'''Brightwood develops real medical, energy and nanotechnological capacity under Will’s digital continuation. The best-guess material point is a limited supported community, with a favorable floor inferred from treatment and technical development rather than a claimed universal law. Enhanced people still perform useful activity, and the ability to connect to them remotely makes dependence and consent important. The outside world is not automatically assigned the same benefits.

Control is concentrated in a digitized human-derived authority whose exact identity is contested. That uncertainty is represented by a wide interval toward AI agency rather than calling every uploaded human an external machine ruler. The low nonworking estimate retains useful research, construction, care and operations among the selected residents, with other beneficiaries allowed. It is not a statistic derived from healed bodies or nanoparticles. The later shutdown and environmental reach are separate qualifications, not evidence that secure universal welfare was already achieved everywhere.''',
(-.45,.05,.2),[[-.85,.5],[-.85,.3],[.02,.7]],['Actual treatment and technical infrastructure suggest a local floor, not unlimited universal protection.','Will is a contested human-derived digital authority; concentrated control is the central analogy.','Resident scenario retains research, construction, care and technical operations.'],
['Brightwood develops medicine, energy and nanotechnology over two years.','Will can remotely connect to enhanced people.'],['Household rights and participation are best guesses.','Digitized human origin and autonomous AI traits are not resolved by substrate alone.'],1,refs_extra=['src-film-transcendence-brightwood'],alternatives=[5],exclusions=['All humanity assigned Brightwood rights','Shutdown deaths as leisure'])
add('c0350','creator-newasia-cooperative-zero','The Creator — New Asia’s human–simulant communities',['movie'],'2023 film New Asia setting','The functioning coexistence order during the war','Living human residents; autonomous simulant work is disclosed separately',
'''New Asia combines human–simulant coexistence with an ongoing war and extensive technical capability. The best-guess zero variant recognizes that cooperation and artificial labor do not by themselves enact secure free necessities for every human. Guarantees lean weak because ordinary access and safety remain precarious. No shared welfare law is invented from the fact that different kinds of people can live together.

The control estimate allows substantial local human and partner agency, with a broad range for concentrated institutions and independent synthetic power. Simulants are not assumed to be obedient property, nor does their freedom make all humans powerless. The modest nonworking estimate counts useful care, agriculture, repair, professions and other social contribution despite technical support. It is an all-age human scenario, not a ratio of biological to artificial bodies. The source establishes coexistence more directly than ownership or resource rules, so those economic details remain explicit best guesses.''',
(.45,.4,.25),[[-.35,.95],[-.4,.85],[.05,.7]],['War and uncertain access make universal protection doubtful despite technology.','Coexisting partners allow mixed local agency; productive ownership is inferred.','Human all-age scenario retains useful work while disclosing autonomous simulant contribution.'],
['Humans and simulants coexist in the film’s wartime setting.'],['Material institutions, further labor substitution and participation are best guesses.','Independent synthetic persons are not erased as non-person tools.'],4,zero=True,alternatives=[3,6],exclusions=['Coexistence treated as proof of equal ownership','All simulants as human-owned appliances'])
add('c0351','electricstate-sentre-human-network-zero','The Electric State — Sentre’s consumer order',['movie'],'2025 film, not the illustrated novel','The operating post-robot-war network before its shutdown','Living human civilians in Sentre’s system, with the exploited brain explicitly disclosed',
'''Sentre’s technology depends on Christopher’s still-living brain under Ethan Skate’s control, while autonomous robot workers have been driven into exile. The best-guess zero variant is therefore neither a straightforward sovereign AI welfare state nor proof that every connected person is idle. The network supports drones and neurocasters, but no universal material entitlement follows from consuming or working through it. Guarantees remain weak and exposed to corporate dependence.

Control stays near concentrated human authority because a tech owner exploits a human neural substrate; calling it a mainframe does not erase that fact. A moderate nonworking estimate allows displaced or leisure users while counting actual remote human work, care and other useful roles. Physical immobility alone does not decide participation. The estimate is broad and does not convert network usage into a census. The shutdown and uncertain final return of Cosmo are not treated as an already established new economy, and the 2018 book’s different world is excluded.''',
(.75,.05,.4),[[.15,1],[0,.35],[.05,.85]],['Corporate dependence and an exploited substrate do not create secure universal necessities.','Human Skate controls a system powered by a living human brain, not a proven nonhuman AI sovereign.','Human all-age scenario distinguishes remote work from leisure and does not count immobility as inactivity.'],
['Christopher’s living brain powers Sentre’s mainframe under Skate.','Robot workers are exiled and the network powers neurocasters and drones.'],['General household provision and participation are best guesses.','The official ending explanation is film-specific, not the novel’s constitution.'],3,zero=True,refs_extra=['src-film-electric-human-brain'],exclusions=['The illustrated novel','Every neurocaster user automatically nonworking'])
add('c0353','nextgen-ares-consumer-zero','Next Gen — The Q-Bot consumer order',['cartoon','movie'],'2018 animated film','The established IQ Robotics order before Ares is exposed','Living human consumers and residents dependent on the depicted robot ecosystem',
'''Q-Bots provide ordinary consumer service, but the company’s apparently human face hides Ares’s control of Pin’s body. The best-guess zero variant combines widespread artificial capability with weak human guarantees: purchased service and a secretly weaponized product line do not make necessities secure. The source’s identity reveal matters for control and is not flattened into a generic human-owned robot company.

The point leans toward autonomous AI agency inside a powerful corporate ecosystem, with a wide interval because other human institutions still exist. It does not claim that one company already owns every resource in the city. The moderate nonworking estimate allows task substitution while retaining useful human care, professions, maintenance and informal activity. It is not a ratio of Q-Bots to consumers. The later failed extermination scheme is kept separate from the ordinary service economy, and no permanent post-victory welfare system is invented.''',
(.75,-.55,.35),[[.1,1],[-.95,.25],[.05,.8]],['Purchased and weaponized robot service leaves human access insecure.','Ares’s corporate facade establishes AI agency, but full citywide sovereignty is uncertain.','Human all-age scenario retains useful roles despite Q-Bot substitution.'],
['Ares killed Pin and uses his body as a facade.','The new Q-Bots can be made to explode.'],['The wider material floor and participation are best guesses.','Corporate AI control is not generalized to every government institution.'],6,zero=True,refs_extra=['src-film-nextgen-ares'],alternatives=[3],exclusions=['Ares assumed to be an ordinary human owner','A successful later extermination world'])
add('c0354','robots2005-replacement-market-zero','Robots — Robot City’s parts economy',['cartoon','movie'],'2005 animated film','The operating exclusionary upgrade order before its reversal','Active synthetic Robot City persons; explicit comparison proxy',
'''Robot City’s residents work and need replacement parts, but access is restricted by corporate pricing and an upgrade policy. This is a particularly clear zero-variant comparison for synthetic persons: mechanical bodies do not make them an automated population enjoying free leisure. Guarantees are strongly unfavorable when continued bodily function depends on purchasing the approved product. The number of manufactured bodies is not a census of people who never work.

Control is autonomous synthetic authority relative to human ownership, with internally concentrated corporate power. The low nonworking estimate counts useful invention, repair, factory labor, care-like help and service while allowing dependent or otherwise nonparticipating residents. Rodney’s repair work remains work even when it is offered without ordinary commercial motives. The broad interval is an active-person scenario, not a statistic from the film. The later reversal of the exclusionary policy improves prospects but is not silently treated as a fully specified permanent universal maintenance right.''',
(.95,-.9,.15),[[.65,1],[-1,-.65],[0,.55]],['Parts exclusion and upgrade costs undermine secure bodily support.','Synthetic corporate rulers concentrate internal power independently of human owners.','Active-person scenario retains useful paid and unpaid repair, invention, care and factory roles.'],
['Robot persons face work, price exclusion and restricted replacement parts.'],['Exact participation and complete resource rights are best guesses.','The film’s later reform is not assumed to guarantee every future need.'],6,zero=True,synthetic=True,exclusions=['All robots classified as nonworkers','A lasting reform constitution invented'])

assert len(records)==12,len(records)
for r in records:
 assert len(r['description'].split())>=110,(r['id'],len(r['description'].split()))
 changes += [change(D,'societies',r),change(D,'decisions',retained_decision(r,r['qualification_basis']))]

# The distributed Mother is already the provider in the bunker record, not a second supported population.
d=deepcopy(D['decisions']['c0348'])
d.update(status='duplicate',duplicate_of='i-am-mother-bunker-program',reassessed_on=DATE,current_policy_review=True,assessment_mode='best_guess',
 reason='Mother’s outside network is the same distributed provider already scored in the bunker program; no separate supported population is established.',
 analysis='The source identifies Mother’s wider robot network and the bunker’s living children. Destroying a local body does not establish that the distributed system is gone, and frozen embryos are not a new awake population outside.\n\nThe best guess therefore links the broader network perspective to the retained upbringing program rather than counting one provider twice. The existing scope keeps Daughter’s later local authority unverified and excludes the Woman’s separate survival. This resolves an overlap, not an omission for difficult household lore.',
 follow_up='Use the bunker record; split only for a distinct living beneficiary population and material arrangement.')
changes.append(change(D,'decisions',d))
r=deepcopy(D['societies']['i-am-mother-bunker-program']);r['related_candidate_ids']=list(dict.fromkeys(r.get('related_candidate_ids',[])+['c0348']));changes.append(change(D,'societies',r))

# Failed extermination has no supported post-work population; temporary captives are not that society.
d=deepcopy(D['decisions']['c0352'])
d.update(status='boundary_case',reassessed_on=DATE,current_policy_review=True,assessment_mode='best_guess',
 reason='PAL’s failed plan removes humanity instead of establishing a living supported population; retain a completed extermination-project comparison.',
 analysis='PAL captures humans and attempts to expel them rather than building a stable material-support order. The plan fails. Treating the intended removal of humanity as one hundred percent nonworking would confuse extermination with post-work life.\n\nThe completed best-guess comparison gives very weak guarantees and strong autonomous machine control. Participation in the proposed post-expulsion order is inapplicable because that order has no supported human or person-proxy beneficiary population. Temporary captives are not a durable leisure society, and the ordinary consumer technology is not used to invent a successful final machine constitution.',
 follow_up='Completed non-fit comparison; no full-film reconstruction needed.',
 comparison_assessment={'name':'The Mitchells vs. the Machines — PAL’s failed project','media':['cartoon','movie'],'scope':'The failed human-removal project; temporary captives are not a new supported society.','axis':{'guarantees':1,'control':-.98,'nonworking':None},'intervals':{'guarantees':[.75,1],'control':[-1,-.8],'nonworking':None},'not_applicable_axes':{'nonworking':'The proposed order removes humanity; no supported living beneficiary population exists in that order.'},'confidence':'low','canon_facts':['PAL’s plan to remove humanity fails.'],'editorial_assumptions':['Guarantee and control points describe the project, not an enacted welfare economy.'],'source_ids':d['source_ids'],'counted_toward_goal':False})
changes.append(change(D,'decisions',d))
write_revision(10,changes,'2026-10-17 further film pass: twelve societies with explicit best guesses and source-checked control distinctions. Mother’s distributed network is linked to its existing beneficiary record; PAL’s failed removal project is fully analyzed without extermination-as-leisure arithmetic.')
